<script setup lang="ts">
import { useRouter } from 'vue-router'
import { computed, getCurrentInstance, onMounted, reactive, ref } from 'vue'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import { useCategoryStore } from '../stores/categories'
import { useTransactionStore } from '../stores/transactions'
import type { Category, Transaction } from '../types'
import { formatCurrency, formatDate } from '../utils/formatters'

const toast = getCurrentInstance()!.appContext.config.globalProperties.$toast as { success: (message: string) => void; error: (message: string) => void }
const router = useRouter(); const transactionStore = useTransactionStore(); const categoryStore = useCategoryStore()
const transactions = ref<Transaction[]>([]); const categories = ref<Category[]>([]); const loading = ref(true); const deleting = ref<Transaction | null>(null)
const filters = reactive({ search: '', type: '', category: '', start: '', end: '', sort: 'date', direction: 'desc' })
onMounted(async () => { [transactions.value, categories.value] = await Promise.all([transactionStore.getAll(), categoryStore.getAll()]); loading.value = false })
const results = computed(() => [...transactions.value].filter((item) => !filters.search || `${item.description} ${item.category}`.toLowerCase().includes(filters.search.toLowerCase())).filter((item) => !filters.type || item.type === filters.type).filter((item) => !filters.category || item.category === filters.category).filter((item) => !filters.start || item.date >= filters.start).filter((item) => !filters.end || item.date <= filters.end).sort((first, second) => { const direction = filters.direction === 'asc' ? 1 : -1; if (filters.sort === 'amount') return (first.amount - second.amount) * direction; if (filters.sort === 'category') return first.category.localeCompare(second.category) * direction; return first.date.localeCompare(second.date) * direction }))
function clearFilters() { Object.assign(filters, { search: '', type: '', category: '', start: '', end: '', sort: 'date', direction: 'desc' }) }
async function confirmDelete() { if (!deleting.value) return; await transactionStore.remove(deleting.value.id); transactions.value = await transactionStore.getAll(); deleting.value = null; toast.success('Transaction deleted.') }
function csvValue(value: string | number) { return `"${String(value).replaceAll('"', '""')}"` }
function downloadCsv() {
  if (!results.value.length) { toast.error('There are no transactions to export.'); return }
  const rows = [['Date', 'Description', 'Category', 'Type', 'Amount'], ...results.value.map((item) => [item.date, item.description, item.category, item.type, item.amount.toFixed(2)])]
  const blob = new Blob([`\ufeff${rows.map((row) => row.map(csvValue).join(',')).join('\n')}`], { type: 'text/csv;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url; link.download = 'transactions.csv'; link.click()
  URL.revokeObjectURL(url)
  toast.success(`${results.value.length} transactions exported as CSV.`)
}
function escapeHtml(value: string) { const entities: Record<string, string> = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }; return value.replace(/[&<>"']/g, (character) => entities[character] || character) }
function exportPdf() {
  if (!results.value.length) { toast.error('There are no transactions to export.'); return }
  const printWindow = window.open('', '_blank')
  if (!printWindow) { toast.error('Unable to open the print dialog. Please allow pop-ups and try again.'); return }
  const rows = results.value.map((item) => `<tr><td>${formatDate(item.date)}</td><td>${escapeHtml(item.description)}</td><td>${escapeHtml(item.category)}</td><td>${item.type}</td><td>${formatCurrency(item.amount)}</td></tr>`).join('')
  printWindow.document.write(`<!doctype html><html><head><title>Transactions</title><style>body{font-family:Arial,sans-serif;color:#172033;padding:24px}h1{margin:0}p{color:#64748b}table{border-collapse:collapse;width:100%;margin-top:24px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e2e8f0;font-size:13px}th{background:#f8fafc;text-transform:uppercase;font-size:11px}</style></head><body><h1>Transactions</h1><p>Exported ${new Date().toLocaleDateString()}</p><table><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Type</th><th>Amount</th></tr></thead><tbody>${rows}</tbody></table></body></html>`)
  printWindow.document.close(); printWindow.focus(); printWindow.print()
  toast.success('Print dialog opened. Choose “Save as PDF” to export.')
}
</script>

<template><section class="mx-auto max-w-7xl p-5 md:p-8 lg:p-10"><div class="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><h1 class="text-3xl font-bold">Transactions</h1><p class="mt-1 text-sm text-muted">Search, organize, and manage every movement.</p></div><div class="flex flex-wrap gap-2"><button class="btn-secondary" :disabled="loading" @click="downloadCsv">Export CSV</button><button class="btn-secondary" :disabled="loading" @click="exportPdf">Export PDF</button><button class="btn-primary" @click="router.push('/transactions/new')">+ Add transaction</button></div></div><div class="mt-8 rounded-card border border-border bg-white p-5 shadow-card"><div class="grid gap-3 md:grid-cols-2 lg:grid-cols-6"><input v-model="filters.search" class="form-input mt-0 lg:col-span-2" placeholder="Search description or category"><select v-model="filters.type" class="form-input mt-0"><option value="">All types</option><option>Income</option><option>Expense</option></select><select v-model="filters.category" class="form-input mt-0"><option value="">All categories</option><option v-for="category in categories" :key="category.id">{{ category.name }}</option></select><input v-model="filters.start" type="date" class="form-input mt-0"><input v-model="filters.end" type="date" class="form-input mt-0"></div><div class="mt-4 flex flex-wrap items-center gap-3"><span class="text-sm text-muted">Sort by</span><select v-model="filters.sort" class="rounded-lg border border-border px-3 py-2 text-sm"><option value="date">Date</option><option value="amount">Amount</option><option value="category">Category</option></select><button class="btn-secondary py-2" @click="filters.direction = filters.direction === 'asc' ? 'desc' : 'asc'">{{ filters.direction === 'asc' ? '↑ Ascending' : '↓ Descending' }}</button><button class="ml-auto text-sm font-semibold text-primary" @click="clearFilters">Clear filters</button></div></div><div class="mt-6 overflow-hidden rounded-card border border-border bg-white shadow-card"><div v-if="loading" class="space-y-3 p-6"><div v-for="number in 5" :key="number" class="h-12 animate-pulse rounded bg-slate-100" /></div><template v-else><div class="hidden grid-cols-[1.5fr_1fr_1fr_1fr_1fr_auto] gap-4 border-b border-border bg-slate-50 px-6 py-3 text-xs font-semibold uppercase tracking-wide text-muted md:grid"><span>Description</span><span>Category</span><span>Date</span><span>Type</span><span>Amount</span><span /></div><div v-for="transaction in results" :key="transaction.id" class="grid gap-2 border-b border-border px-6 py-4 last:border-0 md:grid-cols-[1.5fr_1fr_1fr_1fr_1fr_auto] md:items-center md:gap-4"><div><p class="font-medium">{{ transaction.description }}</p><p class="text-xs text-muted md:hidden">{{ transaction.category }} · {{ formatDate(transaction.date) }}</p></div><span class="hidden text-sm text-muted md:block">{{ transaction.category }}</span><span class="hidden text-sm text-muted md:block">{{ formatDate(transaction.date) }}</span><span :class="transaction.type === 'Income' ? 'text-income' : 'text-expense'" class="text-sm font-medium">{{ transaction.type }}</span><span class="font-bold tabular-nums">{{ formatCurrency(transaction.amount) }}</span><div class="flex gap-3"><button class="text-sm font-semibold text-primary" @click="router.push(`/transactions/${transaction.id}/edit`)">Edit</button><button class="text-sm font-semibold text-expense" @click="deleting = transaction">Delete</button></div></div><div v-if="!results.length" class="p-12 text-center"><p class="font-semibold">No transactions found</p><p class="mt-1 text-sm text-muted">Try changing your filters or add a new transaction.</p></div></template></div><ConfirmDialog :open="Boolean(deleting)" title="Delete transaction?" message="This action cannot be undone." @cancel="deleting = null" @confirm="confirmDelete" /></section></template>
